#include "ast.h"

static ASTNode node_pool[MAX_AST_NODES];
static int node_pool_count = 0;

ASTNode *ast_alloc(void) {
    if (node_pool_count >= MAX_AST_NODES) { fprintf(stderr, "AST node pool exhausted\n"); exit(1); }
    ASTNode *n = &node_pool[node_pool_count++];
    memset(n, 0, sizeof(ASTNode));
    return n;
}

void ast_free_all(void) { node_pool_count = 0; }

void nodelist_init(NodeList *list) { list->items = NULL; list->count = 0; list->cap = 0; }

void nodelist_push(NodeList *list, ASTNode *node) {
    if (list->count >= list->cap) {
        int new_cap = list->cap == 0 ? 8 : list->cap * 2;
        list->items = realloc(list->items, new_cap * sizeof(ASTNode *));
        list->cap = new_cap;
    }
    list->items[list->count++] = node;
}
